select public.ft_test((select relrowsecurity from pg_class where oid='public.ft_bidchecks'::regclass),'Bid answers and verdicts have RLS');
select public.ft_test(not has_table_privilege('anon','public.ft_bidchecks','SELECT'),'No anonymous bid record read');
select public.ft_test(not has_function_privilege('authenticated','public.ft_bidcheck_start(uuid,text,text,text,jsonb,jsonb,jsonb,jsonb)','EXECUTE'),'No browser bid-start RPC');
select public.ft_test(not has_function_privilege('anon','public.ft_lead(uuid,text,boolean,boolean)','EXECUTE'),'No browser opt-in RPC');
select public.ft_admit('mixed-ip','shred',3,10);
select public.ft_bidcheck_start('33333333-3333-4333-8333-333333333333','mixed-ip','Fictional bid check','Prepared test','[]','[]','[]','{"deadline":"2026-12-01","hours":40,"eligibility":"yes","performance":"similar","evidence":"most"}');
select public.ft_admit('mixed-ip','shred',3,10);
do $$begin begin perform public.ft_bidcheck_start('44444444-4444-4444-8444-444444444444','mixed-ip','Fourth mixed use','Prepared test','[]','[]','[]','{}');raise exception 'Fourth mixed use accepted';exception when raise_exception then if SQLERRM not like 'Free tool limit%'then raise;end if;end;end$$;
select public.ft_test(not exists(select from public.ft_jobs where id='44444444-4444-4444-8444-444444444444'),'Rejected admission leaves no job');
select public.ft_test(not exists(select from public.ft_bidchecks where id='44444444-4444-4444-8444-444444444444'),'Rejected admission leaves no bid detail');
select public.ft_test((select n=3 from public.ft_rates where kind='shred'and key='mixed-ip'),'Shred and bid check share three admissions');
select public.ft_test((select as_of=(now()at time zone 'UTC')::date from public.ft_bidchecks where id='33333333-3333-4333-8333-333333333333'),'Scoring date supplied by server, not visitor');
update public.ft_jobs set status='Completed'where id='33333333-3333-4333-8333-333333333333';
select public.ft_lead('33333333-3333-4333-8333-333333333333','hello@tendercrestai.com',false);
select public.ft_test((select teardown_opt_in=false from public.ft_leads where id='33333333-3333-4333-8333-333333333333'),'Original three-argument lead RPC still works and defaults off');
select public.ft_lead('33333333-3333-4333-8333-333333333333','hello@tendercrestai.com',false,true);
select public.ft_test((select teardown_opt_in and not marketing_opt_in from public.ft_leads where id='33333333-3333-4333-8333-333333333333'),'Teardown interest stored independently of marketing');
select public.ft_test((select count(*)=2 from public.ft_leads),'Opt-in retry creates no duplicate lead');
select public.ft_test((select title='Fictional bid check'and source='Prepared test'from public.ft_leads where id='33333333-3333-4333-8333-333333333333'),'Opt-in preserves source metadata');
insert into public.ft_events(id,name)values('55555555-5555-4555-8555-555555555555','bidcheck_completed');
update public.ft_jobs set expires_at=now()-interval'1 second'where id='33333333-3333-4333-8333-333333333333';select public.ft_cleanup();
select public.ft_test(not exists(select from public.ft_bidchecks),'Existing cleanup expires bid answers and verdict by cascade');
select public.ft_test((select teardown_opt_in from public.ft_leads where id='33333333-3333-4333-8333-333333333333'),'Only lead interest metadata remains after source expiry');
select 'Bid-check SQL checks passed' as result;
